const M=WalletModel;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=n=>'¥ '+fmt(n);
const STORE='crossborder-wallet-prototype-v1';
let S;try{S=JSON.parse(localStorage.getItem(STORE));}catch{}if(!S||S.version!==1)S=M.seed();
let C={page:'home',mode:'app',stage:0,fields:{},tab:'order',flow:'pay',scenario:'normal',privacy:false};
let popup=false,modalState=null,toastTimer,returnToPay=null;
function persist(){try{localStorage.setItem(STORE,JSON.stringify(S));}catch{}}
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',wallet:'M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6m18 7h-6v4h6M16 15h1',down:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',up:'M12 17V4m-5 5 5-5 5 5M4 17v4h16v-4',pay:'M3 7h18v13H3ZM3 11h18M6 16h4M6 3h12',bank:'m3 8 9-5 9 5ZM5 11v7m5-7v7m4-7v7m5-7v7M3 21h18',exchange:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',settings:'M9 3h6l1 4 4 1v7l-4 1-1 5H9l-1-5-4-1V8l4-1Zm3 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',list:'M6 3h12v18H6ZM9 7h6M9 11h6M9 15h4',gift:'M3 9h18v4H3ZM5 13v8h14v-8M12 9v12M12 9C3 9 5 1 9 4l3 5Zm0 0c9 0 7-8 3-5Z',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M9 8a3 3 0 1 1 5 2c-1 1-2 1-2 3m0 4h.01',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5Zm5 3h4M12 2v2',chevron:'m9 5 7 7-7 7',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M12 11v6m0-10h.01',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Zm-4 9 3 3 5-5',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M12 6v6l4 3',globe:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M2 12h20M12 2c6 6 6 14 0 20M12 2c-6 6-6 14 0 20',box:'m12 2 9 5v10l-9 5-9-5V7Zm-9 5 9 5 9-5M12 12v10M7 4l10 6',plus:'M12 4v16M4 12h16',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16m6-2 6 6',refresh:'M20 7A9 9 0 1 0 21 15M20 2v5h-5',sortup:'m6 14 6-6 6 6',sortdown:'m6 9 6 6 6-6',flow:'M3 4h6v5H3ZM15 15h6v5h-6M6 9v9h9M9 6h9v9',lock:'M5 10h14v11H5ZM8 10V6a4 4 0 0 1 8 0v4m-4 5v2',copy:'M8 8h13v13H8ZM16 8V3H3v13h5',link:'M10 14 14 10M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',download:'M12 3v13m-5-5 5 5 5-5M4 20h16',card:'M3 5h18v14H3ZM3 10h18M6 15h3',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7'};
function icon(n){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.wallet}"/></svg>`;}
function b(text,action,cls='',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function link(text,action,attrs=''){return `<button type="button" class="textbtn" data-action="${action}" ${attrs}>${text}</button>`;}
function tag(text,type=''){return `<span class="tag ${type}">${text}</span>`;}
function note(text,type=''){return `<div class="notice ${type}">${icon(type==='success'?'check':'info')}<div>${text}</div></div>`;}
function kv(k,v,cls=''){return `<div class="kv ${cls}"><span class="key">${k}</span><span class="val">${v}</span></div>`;}
function head(title,subtitle='',right=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="headright">${right}</div></div>`;}
function field(label,name,value='',help='',attrs=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" value="${esc(value)}" ${attrs}>${help?`<div class="help">${help}</div>`:''}</div>`;}
function select(label,name,values,current){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${values.map(x=>`<option value="${esc(x[0])}" ${current===x[0]?'selected':''}>${esc(x[1])}</option>`).join('')}</select></div>`;}
function amountField(label,name,value,currency,help='',max=false){return `<div class="field"><label for="${name}">${label}</label><div class="money-input"><input id="${name}" name="${name}" value="${esc(value)}" inputmode="decimal" placeholder="0.00" autocomplete="off">${max?link('全部','max'):''}<span class="unit">${currency}</span></div>${help?`<div class="help">${help}</div>`:''}</div>`;}
function steps(names,active){return `<div class="steps">${names.map((x,i)=>`${i?'<div class="step-line"></div>':''}<div class="step ${i===active?'active':i<active?'done':''}"><span>${i<active?'✓':i+1}</span>${x}</div>`).join('')}</div>`;}
function error(){return C.error?`<div class="error-text" role="alert">${esc(C.error)}</div>`:'';}
function num(name){const x=String(C.fields[name]??'').trim();if(!/^\d+(\.\d{1,2})?$/.test(x))return NaN;return Number(x);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function fresh(page,options={}){C={...C,page,mode:'app',stage:0,fields:{},tab:page==='settings'?'order':'1688',error:'',quote:null,record:null,scenario:'normal',...options};if(page==='transfer')C.fields={source:'intl',currency:'USD',amount:'1000',...C.fields};if(page==='withdraw')C.fields={currency:'CNY',bank:'b1',amount:'5000',...C.fields};if(page==='fx')C.fields={from:'USD',to:'CNY',amount:'1000',...C.fields};if(page==='settings')C.draft=JSON.parse(JSON.stringify(S.settings));popup=false;render();window.scrollTo(0,0);}
function nav(page,options={}){fresh(page,options);history.replaceState(null,'','#'+page);}
function addTx(data){const record={id:'CB'+Date.now().toString().slice(-12),time:'2026-11-08 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'}),...data};S.tx.unshift(record);persist();C.record=record;return record;}
const navs=[['home','wallet','钱包总览'],['transfer','down','转入'],['pay','pay','付款'],['withdraw','up','提现'],['fx','exchange','汇兑'],['settings','settings','支付设置'],['records','list','资金明细']];
function shell(content){return `<header class="topbar"><div class="brand"><span class="brandmark"><em>e</em> 阿里国际站</span><span class="divider brandcontext"></span><span class="brandcontext">商家工作台</span></div><div class="topright">${tag('交互原型 · 演示数据','orange')}<button class="iconbtn" aria-label="消息提醒" data-action="notifications">${icon('bell')}</button><button class="iconbtn" aria-label="帮助中心" data-nav="help">${icon('help')}</button><span class="divider"></span><span class="tiny company">杭州远帆贸易有限公司</span><button class="avatar" data-action="profile" aria-label="商家账户">远帆</button></div></header><aside class="sidebar"><div class="workspace"><div class="square">${icon('wallet')}</div><div><b style="font-size:14px">资金管理</b><div class="eyebrow" style="margin-top:3px;font-size:8px">BUSINESS WALLET</div></div></div><div class="navsection">跨境宝</div>${navs.map(([id,ic,n])=>`<button class="navitem ${C.page===id&&C.mode==='app'?'active':''}" data-nav="${id}">${icon(ic)}<span>${n}</span></button>`).join('')}<div class="navsection" style="margin-top:15px">服务</div><button class="navitem ${C.page==='benefits'?'active':''}" data-nav="benefits">${icon('gift')}<span>权益中心</span></button><button class="navitem ${C.page==='help'?'active':''}" data-nav="help">${icon('help')}<span>帮助中心</span></button><div class="sidebottom"><div class="sidehelp"><b>${icon('shield')} 资金动态，清晰可查</b>每一笔收付都有迹可循</div><div class="tiny muted" style="text-align:center;margin-top:18px;font-size:9px">Alibaba.com Pay × 1688</div></div></aside><div class="proto"><div class="prototabs"><button class="${C.mode==='app'?'active':''}" data-mode="app">体验原型</button><button class="${C.mode==='flow'?'active':''}" data-mode="flow">用户动线</button><button class="${C.mode==='spec'?'active':''}" data-mode="spec">设计说明</button></div><div class="protohint"><i class="dot"></i><span>PC 端 · 所有操作均为模拟</span><span>V1.0 / 2026.11</span></div></div><main class="main ${C.mode!=='app'?'review':''}">${content}</main><div class="designbar"><button data-action="scenario">${icon('flow')} 情景演示</button><span style="color:#dbe2ed">|</span><button data-action="reset">${icon('refresh')} 重置</button></div>${popup?scenarioPopover():''}`;}
function render(){const views={home,transfer:transferPage,pay:payPage,withdraw:withdrawPage,fx:fxPage,settings:settingsPage,records:recordsPage,benefits:benefitsPage,help:helpPage};$('#app').innerHTML=shell((returnToPay&&C.mode==='app'&&C.page!=='pay'?`<div class="flow-link"><span>已保留待付款订单 ${esc(returnToPay.order)} · 货款 ${money(returnToPay.amount)}</span>${link('返回付款，重新计算 '+icon('arrow'),'return-pay')}</div>`:'')+(C.mode==='flow'?flowPage():C.mode==='spec'?specPage():(views[C.page]||home)()));}
function sourceCard(id){const a=S.accounts[id],val=M.equivalent(a.balances),isWallet=id==='wallet';return `<div class="account-card"><div class="account-top"><span class="source-icon ${id}">${id==='wallet'?icon('wallet'):id==='acp'?'AP':'a'}</span>${a.name}${id==='acp'?'<span class="tiny muted" style="font-weight:400">Alibaba Pay</span>':''}${tag(isWallet?'钱包账户':a.authorized?'已授权':'待授权',isWallet?'blue':a.authorized?'green':'orange')}</div><div class="tiny muted">${isWallet?'钱包可用余额':'可调用余额'} · 折合 CNY</div><div class="account-value mono ${C.privacy?'privacy':''}">${fmt(a.authorized?val:0)}</div><div class="currency-line ${C.privacy?'privacy':''}">${Object.entries(a.balances).filter(([c,n])=>n).map(([c,n])=>`<span>${c} ${fmt(n)}</span>`).join('')}</div><div class="account-bottom"><span>${isWallet?'资金存放于跨境宝':'资金仍留在'+a.name+'账户'}</span>${link(a.authorized?'查看明细 '+icon('chevron'):'去授权 '+icon('chevron'),'account',`data-id="${id}"`)}</div></div>`;}
function txTable(rows,compact=false){return `<div class="table-wrap"><table><thead><tr><th>交易内容</th>${compact?'':'<th>资金账户</th>'}<th>金额</th><th>状态</th><th></th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td><div class="title">${esc(t.title)}</div><div class="sub">${esc(t.time)}</div></td>${compact?'':`<td>${esc(S.accounts[t.source]?.name||'跨境宝')}</td>`}<td class="mono ${['收款','转入'].includes(t.type)?'green':''}">${esc(t.display)}</td><td><span class="${t.status==='已完成'?'green':t.status.includes('失败')||t.status==='已退回'?'red':'orange'} tiny"><i class="status-dot"></i>${esc(t.status)}</span></td><td>${link('详情','tx',`data-id="${t.id}"`)}</td></tr>`).join(''):'<tr><td colspan="5"><div class="empty">没有符合条件的记录</div></td></tr>'}</tbody></table></div>`;}
function home(){const total=M.total(S),avail=M.available(S),frozen=M.round(Object.values(S.accounts).reduce((n,a)=>n+M.equivalent(a.frozen),0));return `${head('跨境宝','让每一笔外销收入，成为下一笔采购的起点。',`${icon('refresh')} 资金已同步 · 刚刚 ${link('查看账户','account','data-id="all"')}`)}<div class="hero-grid"><section class="hero"><div class="hero-label">总资产 · 折合人民币 <button class="iconbtn" data-action="privacy" aria-label="显示或隐藏金额">${icon('eye')}</button><span style="margin-left:auto;font-size:10px;opacity:.65">${icon('shield')} 3 个资金账户</span></div><div class="balance ${C.privacy?'privacy':''}"><small>¥</small>${fmt(total)}</div><div class="herobottom"><div class="herostat"><div class="label">可采购余额合计 ${link(icon('info'),'quota','aria-label="查看可采购余额说明"')}</div><div class="value mono ${C.privacy?'privacy':''}">¥ ${fmt(avail)}</div></div><div class="herostat"><div class="label">冻结 / 处理中</div><div class="value mono ${C.privacy?'privacy':''}">¥ ${fmt(frozen)}</div></div><div style="margin-left:auto;align-self:flex-end;z-index:1">${link('查看资产构成 '+icon('chevron'),'quota')}</div></div></section><section class="commerce-card"><div><div class="commerce-title">${icon('globe')} 外销内采，一路畅通</div><p>海外收款，直接用于国内采购</p></div><div class="commerce-flow"><b>国际站收款</b>${icon('arrow')}<b>跨境宝</b>${icon('arrow')}<b>1688 采购</b></div>${b('去采购付款 '+icon('arrow'),'go-pay')}</section></div><div class="quick-actions">${[['transfer','down','转入','多渠道资金转入'],['pay','pay','付款','采购与供应商付款'],['withdraw','up','提现','转至企业银行卡'],['fx','exchange','汇兑','多币种灵活兑换'],['settings','settings','支付设置','管理扣款顺序']].map(([id,ic,title,sub])=>`<button class="quick-action" data-nav="${id}"><div class="action-icon">${icon(ic)}</div><div><strong>${title}</strong><span>${sub}</span></div></button>`).join('')}</div><div class="sectionhead"><h2>我的资金账户 <span class="meta">统一使用，分别记账</span></h2>${link('管理资金来源 '+icon('chevron'),'go-accounts')}</div><div class="account-grid">${['wallet','acp','intl'].map(sourceCard).join('')}</div><div class="lower-grid"><section class="panel flush"><div class="panel-title"><h2>最近资金动态</h2>${link('全部明细 '+icon('chevron'),'go-records')}</div>${txTable(S.tx.slice(0,4),true)}</section><aside><section class="panel" style="padding:20px"><div class="sectionhead" style="margin-bottom:2px"><h2>待办事项</h2>${tag(S.tx.some(t=>t.order==='202611080126'&&t.status==='已完成')?'1':'2','orange')}</div><div class="task-item"><div class="task-icon">${icon('pay')}</div><div><h4>${S.tx.some(t=>t.order==='202611080126'&&t.status==='已完成')?'外销关联采购已付款':S.tx.some(t=>t.order==='202611080126'&&t.status==='处理中')?'外销关联采购付款处理中':'1 笔外销关联采购待付款'}</h4><p>自动生成采购单 · 点击查看状态</p></div>${link(icon('chevron'),'order','data-order="normal" aria-label="查看关联采购单"')}</div><div class="task-item"><div class="task-icon" style="background:#edf4ff;color:#6e90c4">${icon('clock')}</div><div><h4>国际站待结算收款</h4><p>USD 3,000.00 · 尚不可用于采购</p></div>${link(icon('chevron'),'pending-funds','aria-label="查看待结算资金"')}</div></section><section class="panel benefit" style="padding:19px 22px"><div class="sectionhead" style="margin:0"><h2>我的支付权益</h2>${icon('gift')}</div><div class="rate">0.125<span>%</span></div>${tag('采购服务费 · 示例','blue')}<p>付款前自动展示费用，安心安排每笔资金</p><div style="margin-top:12px">${link('查看权益详情 '+icon('chevron'),'go-benefits')}</div></section></aside></div><div class="design-note">总资产覆盖跨境宝、ACP 与国际站余额，统一按演示汇率折算；银行卡余额不计入。实际付款可用金额以确认页为准。</div>`;}
function transferPage(){const f=C.fields,src=f.source||'intl',a=S.accounts[src];if(C.stage===3)return resultPage();if(C.stage===0)return `${head('转入','连接多渠道收款，让资金在一个钱包里协同。',b('转入记录','transfer-records','',`aria-label="查看转入记录"`))}${steps(['选择资金来源','填写转入信息','确认与结果'],0)}<div class="form-layout"><section class="panel form-panel"><h2 style="margin-bottom:9px">资金从哪里来？</h2><p class="tiny muted" style="margin-bottom:24px">可保留原账户余额用于采购，也可主动转入跨境宝。</p><div class="choice-grid">${[['intl','a','阿里国际站','转入已结算的外销货款'],['acp','AP','ACP 余额','Alibaba Pay 收款工具余额'],['bank','card','银行转账','企业同名银行账户汇入'],['channel','globe','其他收款渠道','连接其他平台或 PSP 收款']].map(([id,ic,n,sub])=>`<button class="choice" data-action="transfer-select" data-id="${id}"><span class="source-icon ${id}">${['card','globe'].includes(ic)?icon(ic):ic}</span><div><h3>${n}</h3><p>${sub}</p></div>${icon('chevron')}</button>`).join('')}</div>${note('国际站和 ACP 已授权的可用余额，未转入跨境宝也能直接采购。账户间转入只改变钱存放的位置，总资产不增加。')}<div class="sectionhead"><h3 style="font-size:13px">收款入账规则</h3>${link('管理规则 '+icon('chevron'),'go-accounts')}</div>${kv('国际站新到账资金',S.settings.route.intl==='keep'?'保留原账户，可用于采购':'结算后自动转入跨境宝')}${kv('ACP 新到账资金',S.settings.route.acp==='keep'?'保留原账户，可用于采购':'结算后自动转入跨境宝')}</section><aside class="panel side-info"><h3>收款之后，资金怎么走？</h3><div class="timeline"><div class="timeline-item">客户付款或平台结算<p>关联外销订单、收款单</p></div><div class="timeline-item">到达对应渠道账户<p>处理中和待结算资金单独展示</p></div><div class="timeline-item">成为可用余额<p>完成结算且可支配后，更新可采购余额</p></div><div class="timeline-item">按你的规则使用<p>留在原账户，或转入跨境宝</p></div></div></aside></div>`;
if(src==='bank')return bankTransferPage();if(src==='channel')return channelPage();
const currency=f.currency||'USD',balance=a.balances[currency]||0;
return `${head('转入跨境宝',`从${a.name}转入，让资金集中管理。`,link(icon('back')+' 返回资金来源','transfer-back'))}${steps(['选择资金来源','填写转入信息','确认与结果'],C.stage===1?1:2)}<div class="form-layout"><section class="panel form-panel">${C.stage===1?`<div class="bankcard"><span class="source-icon ${src}">${src==='intl'?'a':'AP'}</span><div><b style="font-size:13px">${a.name} → 跨境宝</b><p>杭州远帆贸易有限公司 · 同主体账户</p></div>${tag(a.authorized?'已授权':'待授权',a.authorized?'green':'orange')}</div>${!a.authorized?note('此资金来源尚未授权，授权后才可转入或用于采购。','warn'):''}${select('转入币种','currency',Object.keys(M.rates).map(c=>[c,c]),currency)}${amountField('转入金额','amount',f.amount,currency,`可转入 ${currency} ${fmt(balance)} · 冻结及待结算金额不计入`,true)}${kv('预计到账','转入完成后更新钱包余额')}${kv('转入费用',currency+' 0.00')}${error()}<div class="formfooter">${b('返回','transfer-back')}${b(a.authorized?'下一步':'去授权',a.authorized?'transfer-next':'auth-source','primary')}</div>`:`<h2 style="margin-bottom:25px">确认转入信息</h2>${kv('转出账户',a.name)}${kv('转入账户','跨境宝 · 同币种账户')}${kv('转入金额',currency+' '+fmt(f.amount))}${kv('转入费用',currency+' 0.00')}${kv('实际到账',currency+' '+fmt(f.amount),'total')}${note('转入后将相应减少'+a.name+'余额，并增加跨境宝余额。三方总资产不变。')}${error()}<div class="formfooter">${b('上一步','transfer-edit')}${b('确认转入','transfer-confirm','primary')}</div>`}</section><aside class="panel side-info"><h3>当前资金情况</h3>${kv(a.name+'可用',currency+' '+fmt(balance))}${kv('跨境宝可用',currency+' '+fmt(S.accounts.wallet.balances[currency]))}<div class="divider-line"></div><p>仅可转入已结算、可支配的资金。采购占用、冻结和未结算资金不会被重复使用。</p><p>收款是货款到账，实际利润需要结合采购、物流等成本另行核算。</p>${link('查看可采购余额','quota')}</aside></div>`;}
function bankTransferPage(){const f=C.fields;return `${head('银行转账转入','使用同名企业银行账户，汇入跨境宝。',link(icon('back')+' 返回资金来源','transfer-back'))}${steps(['选择资金来源','填写转入信息','确认与结果'],1)}<div class="form-layout"><section class="panel form-panel">${select('入账币种','currency',Object.keys(M.rates).map(c=>[c,c]),f.currency)}${amountField('计划转入金额','amount',f.amount,f.currency)}${note('以下收款信息仅用于原型演示，不可用于真实汇款。','warn')}<div class="receipt" style="margin:0;max-width:none">${kv('收款主体','杭州远帆贸易有限公司（演示）')}${kv('收款银行','演示银行 · 跨境收款专户')}${kv('收款账号','DEMO **** 8632')}${kv('汇款附言','DEMO-YF-20261108')}</div><p class="tiny muted" style="margin-top:17px">实际到账金额以银行入账为准。提交转入意向不会增加可用余额。</p>${error()}<div class="formfooter">${b('复制收款信息','copy-bank')}${b('我已汇款（演示）','bank-intent','primary')}</div></section><aside class="panel side-info"><h3>到账后才能使用</h3><p>完成银行汇款后，在转入详情中查看入账进度。待入账金额不会计入可采购余额。</p><p>若汇款主体或附言不一致，进入人工核对；修正后继续原交易，不重复入账。</p></aside></div>`;}
function channelPage(){const f=C.fields;return `${head('连接其他收款渠道','为更多外销渠道预留统一的收款入口。',link(icon('back')+' 返回资金来源','transfer-back'))}<div class="form-layout"><section class="panel form-panel">${select('渠道类型','channelType',[['market','其他电商平台'],['psp','第三方收款服务（PSP）'],['direct','线下贸易收款']],f.channelType||'market')}${field('渠道名称','channelName',f.channelName??'海外独立站','例如：独立站店铺或第三方收款服务，当前为连接流程演示。')}${field('渠道商户号','merchant',f.merchant??'DEMO-YF001','仅填写演示商户号，不填写密码或密钥。')}${select('新资金入账位置','channelRoute',[['wallet','转入跨境宝'],['source','留在渠道账户（需支持授权付款）']],f.channelRoute||'wallet')}${note('新增渠道需要先验证商户主体与收付款能力。未完成连接前，不纳入总资产和可采购余额。')}${error()}<div class="formfooter">${b('返回','transfer-back')}${b('确认连接（演示）','channel-connect','primary')}</div></section><aside class="panel side-info"><h3>可扩展的资金来源</h3><p>每个渠道独立保留收款币种、资金状态、原始流水和用途限制；钱包统一提供操作入口。</p><p>同一笔资金仅在实际所在的账户计入资产，渠道连接不会自动复制余额。</p></aside></div>`;}
function orderOpen(kind='normal'){const oid=kind==='shortage'?'202611080132':'202611080126';const previous=S.tx.find(t=>t.type==='付款'&&t.order===oid&&['已完成','处理中'].includes(t.status));if(previous&&kind!=='other'){nav('pay',{stage:3,record:previous});toast('已存在该订单付款，展示原交易结果');return;}returnToPay=null;const amount=kind==='shortage'?360000:kind==='small'?18000:120000;nav('pay',{stage:1,fields:{external:kind==='shortage'?'':'TA202611080328',amount:String(amount),supplier:kind==='other'?'深圳市远航包装有限公司':'义乌市星合日用品商行',order:kind==='shortage'?'202611080132':'202611080126',kind:kind==='other'?'other':'1688',card:false,agreed:false},scenario:kind==='shortage'?'shortage':'normal'});}
function payPage(){if(C.stage===3)return resultPage();if(C.stage===0)return `${head('付款','外销订单关联采购，或向其他供应商付款。',b('支付设置 '+icon('settings'),'go-settings'))}<div class="subtabs"><button class="${C.tab!=='other'?'active':''}" data-paytab="1688">1688 采购</button><button class="${C.tab==='other'?'active':''}" data-paytab="other">其他供应商付款</button></div>${C.tab==='other'?otherPaymentForm():`${note('国际站外销订单可关联生成 1688 采购单。付款前按你的支付顺序分配资金；自动付款需单独授权。')}<section class="panel"><div class="sectionhead"><h2>采购订单</h2><span class="tiny muted">可采购余额合计 <b class="mono" style="color:#466182">${money(M.available(S))}</b></span></div>${[['normal','折叠式收纳箱 · 2,000 件',120000,'外销关联采购','TA202611080328'],['shortage','便携式保温杯 · 6,000 件',360000,'自主采购','']].map(([id,n,amt,t,ta])=>`<div class="order"><div class="order-visual">${icon('box')}</div><div class="order-body"><h3>${n}</h3><span class="tiny muted">义乌市星合日用品商行</span><p>${tag(t,id==='normal'?'blue':'')} ${ta?'关联外销单 '+ta:'1688 订单 202611080132'}</p></div><div class="order-amount"><strong class="mono">${money(amt)}</strong><span class="tiny muted">货款 · 不含支付服务费</span></div>${b(S.tx.some(t=>t.type==='付款'&&t.order===(id==='normal'?'202611080126':'202611080132')&&['已完成','处理中'].includes(t.status))?'查看付款':'去付款','order','primary small',`data-order="${id}"`)}</div>`).join('')}</section><div class="panel side-info"><h3>自动采购如何衔接？</h3><p style="margin:0">外销订单满足采购条件 → 生成关联采购单 → 校验可用资金与付款授权 → 按规则付款 → 回写采购状态。收款仍待结算时，采购单可先生成，付款进入待办。</p><div style="margin-top:13px">${link('设置自动采购付款 '+icon('chevron'),'go-auto')}</div></div>`}`;
const f=C.fields;if(!S.settings.card)f.card=false;const amount=num('amount'),q=M.quote(S,amount,!!f.card),valid=Number.isFinite(amount)&&amount>0;C.quote=q;const available=M.eligible(S);return `${head(f.kind==='other'?'供应商付款确认':'采购付款确认','付款前确认收款方、费用和资金来源。',link(icon('back')+' 返回付款列表','pay-back'))}${steps(['选择订单','确认扣款','付款结果'],1)}<div class="form-layout"><section class="panel form-panel"><div class="sectionhead"><h2>${esc(f.supplier)}</h2>${tag(f.kind==='other'?'其他供应商':'1688 采购','blue')}</div>${kv('采购订单',esc(f.order))}${f.kind!=='other'?(f.external?kv('关联外销订单',esc(f.external)):''):kv('收款账户',esc(f.recipient||'DEMO **** 9316'))}${amountField('本次付款货款','amount',f.amount,'CNY','修改金额可体验余额不足等场景。')}${kv('支付服务费（示例 0.125%）',money(q.fee))}${kv('合计需支付',money(q.due),'total')}${!valid?note('请输入大于 0 的金额，最多保留两位小数。','error'):q.gap&&!f.card?`<div class="notice error">${icon('info')}<div><b>可采购余额不足，还差 ${money(q.gap)}</b><br>本次需支付 ${money(q.due)}，当前可用于本次付款 ${money(available)}。${!S.settings.fx?'自动汇兑已关闭，外币余额未参与本次付款。':''}<div style="display:flex;gap:16px;margin-top:9px">${link('去转入补足','pay-topup')}${S.settings.card?link('使用银行卡补款','card-fallback'):link('设置银行卡补款','go-card')}</div></div></div>`:''}<div class="sectionhead" style="margin-top:24px"><h3 style="font-size:13px">本次扣款方案</h3>${link('调整支付顺序','go-settings')}</div><div style="border:1px solid var(--line);border-radius:8px;padding:0 16px">${q.allocations.map((a,i)=>`<div class="plan-row"><span class="plan-num">${i+1}</span><div class="plan-name">${S.accounts[a.id].name}<p>${a.parts.map(p=>`${p.currency} ${fmt(p.native)}${p.currency!=='CNY'?' → 支付 CNY '+fmt(p.base):''}${p.change?'；兑换余款 CNY '+fmt(p.change)+' 留存原账户':''}`).join('<br>')}</p></div><b class="plan-amount">${money(a.value)}</b></div>`).join('')}${f.card&&q.cardAmount?`<div class="plan-row"><span class="plan-num">${q.allocations.length+1}</span><div class="plan-name">招商银行 · 尾号 6288<p>本次单独授权补足差额</p></div><b class="plan-amount">${money(q.cardAmount)}</b></div>`:''}${q.allocations.length===0?'<div class="empty" style="padding:25px">暂无可用于本次付款的余额</div>':''}</div>${q.fx?`<div class="quote-strip"><span>演示参考汇率 USD/CNY 7.1000 · EUR/CNY 8.0000</span>${tag(C.expired?'报价已过期':'确认时重新校验',C.expired?'orange':'blue')}</div>`:''}${C.expired?note('汇率报价已过期，请重新获取扣款方案后确认。','warn'):''}<label class="checkrow"><input type="checkbox" name="agreed" ${f.agreed?'checked':''}><span>确认收款方及扣款方案${q.fx?'，同意按展示汇率进行本次币种转换':''}${f.card?'，并授权银行卡补款':''}。</span></label>${error()}<div class="formfooter">${b('返回','pay-back')}${C.expired?b('刷新报价','refresh-quote','primary'):b('确认付款 '+money(q.due),'pay-confirm','primary',(!q.ok||!valid?'disabled':''))}</div></section><aside><div class="panel side-info"><h3>本次付款可用资金</h3>${kv('三方可采购余额合计',money(M.available(S)))}${!S.settings.fx?kv('本次仅使用人民币',money(available)):''}${kv('银行卡补款',S.settings.card?'已开启 · 每次确认':'未开启')}<div class="divider-line"></div><p>按支付设置的账户顺序扣款，每个账户内优先使用人民币。不足部分在获授权后换汇。</p><p>冻结、待结算、用途不匹配或授权失效的金额不参与此次付款。</p>${link('查看额度构成','quota')}</div><div class="panel side-info"><h3>付款结果会同步到哪里？</h3><p>采购单与钱包资金明细同步更新。拆分扣款会归入同一笔付款，方便追溯到外销订单。</p><p>发生退款时，本方案建议按原扣款来源与比例退回；具体退款和费用规则待业务确认。</p></div></aside></div>`;}
function otherPaymentForm(){return `<div class="form-layout"><section class="panel form-panel"><h2 style="margin-bottom:25px">填写供应商信息</h2>${field('收款供应商','supplier',C.fields.supplier??'深圳市远航包装有限公司')}${field('收款账户','recipient',C.fields.recipient??'DEMO **** 9316','演示账户，实际付款需校验账户主体与用途。')}${field('业务单号','order',C.fields.order??'PO202611080021')}${amountField('付款货款','amount',C.fields.amount??'18000','CNY')}${field('付款用途','purpose',C.fields.purpose??'包装材料采购')}${error()}<div class="formfooter">${b('下一步','other-next','primary')}</div></section><aside class="panel side-info"><h3>不限于 1688 采购</h3><p>为其他供应商提供独立付款入口，仍使用统一的资金来源、扣款顺序和账单。</p><p>不同场景可用的账户能力需要逐笔检查。具体可用来源将在确认页按本次付款场景校验。</p></aside></div>`;}
function withdrawPage(){if(C.stage===3)return resultPage();const f=C.fields,c=f.currency||'CNY',banks=S.banks.filter(x=>x.currency===c),bank=banks.find(x=>x.id===f.bank)||banks[0],fee=c==='CNY'?2:c==='USD'?5:4,amt=num('amount'),available=S.accounts.wallet.balances[c];if(bank)f.bank=bank.id;return `${head('提现','将跨境宝可用余额，提至已验证的同名银行卡。',b('管理银行卡','banks'))}${steps(['填写提现信息','确认提现','到账结果'],C.stage===0?0:1)}<div class="form-layout"><section class="panel form-panel">${C.stage===0?`${select('提现币种','currency',Object.keys(M.rates).map(c=>[c,c]),c)}<div class="field"><div class="field-head"><span>到账银行卡</span>${link('+ 添加银行卡','add-bank')}</div>${banks.length?banks.map(x=>`<button class="bankcard ${f.bank===x.id?'selected':''}" style="width:100%;text-align:left" data-action="select-bank" data-id="${x.id}"><span class="bankicon">${icon('bank')}</span><span><b style="font-size:13px">${esc(x.name)} · ${x.tail}</b><p>杭州远帆贸易有限公司 · ${x.currency}</p></span>${tag(f.bank===x.id?'已选择':'同名账户',f.bank===x.id?'blue':'')}</button>`).join(''):note('还没有支持此币种的银行卡，请先添加。','warn')}</div>${amountField('提现到账金额','amount',f.amount,c,`可用 ${c} ${fmt(available)} · 另收 ${c} ${fmt(fee)} 提现费（示例）`,true)}${kv('预计扣除',c+' '+fmt((amt||0)+fee))}${kv('预计到账','1–2 个工作日（演示）')}${error()}<div class="formfooter">${b('下一步','withdraw-next','primary',!bank?'disabled':'')}</div>`:`<h2 style="margin-bottom:25px">确认提现信息</h2>${kv('提现账户','跨境宝 · '+c)}${kv('到账银行卡',esc(bank?.name)+' · '+esc(bank?.tail))}${kv('账户主体','杭州远帆贸易有限公司')}${kv('到账金额',c+' '+fmt(amt))}${kv('提现服务费',c+' '+fmt(fee))}${kv('合计扣除',c+' '+fmt(amt+fee),'total')}${note('提交后，提现金额和费用将暂时占用。银行处理成功后扣除；退回时释放占用，不重复扣款。')}${error()}<div class="formfooter">${b('上一步','withdraw-edit')}${b('确认提现','withdraw-confirm','primary')}</div>`}</section><aside class="panel side-info"><h3>哪些资金可以提现？</h3><p>此入口提现的是跨境宝可用余额。留在国际站或 ACP 的资金，可先按对应账户能力转入跨境宝。</p><p>不同币种分别核算。若希望人民币到账，可先将外币换汇，再发起人民币提现。</p>${link('去汇兑 '+icon('chevron'),'go-fx')}<div class="divider-line"></div>${kv('跨境宝 '+c+' 可用',fmt(available))}${kv('跨境宝 '+c+' 冻结',fmt(S.accounts.wallet.frozen[c]))}</aside></div>`;}
function fxCalc(){const f=C.fields,amount=num('amount')||0,fee=M.round(amount*.001),rate=M.rates[f.from]/M.rates[f.to];return {amount,fee,rate,received:M.round((amount-fee)*rate)};}
function fxPage(){if(C.stage===3)return resultPage();const f=C.fields,q=fxCalc(),wallet=S.accounts.wallet;return `${head('汇兑','在跨境宝账户内兑换币种，为下一笔付款做好准备。',link('汇兑记录','fx-records'))}${steps(['填写兑换金额','确认报价','兑换结果'],C.stage===0?0:1)}<div class="form-layout"><section class="panel form-panel">${C.stage===0?`<div class="exchange-box">${select('卖出币种','from',Object.keys(M.rates).map(c=>[c,c]),f.from)}${amountField('卖出金额','amount',f.amount,f.from,`可用 ${f.from} ${fmt(wallet.balances[f.from])}`,true)}</div><button class="exchange-direction" data-action="swap-fx" aria-label="交换买入和卖出币种">${icon('exchange')}</button><div class="exchange-box receive">${select('买入币种','to',Object.keys(M.rates).map(c=>[c,c]),f.to)}<div class="tiny muted">预计收到</div><div class="mono" style="font-size:28px;margin:8px 0" id="fx-received">${fmt(q.received)} <small style="font-size:14px;color:#7790b0">${f.to}</small></div></div><div class="quote-strip"><span>演示汇率 · 1 ${f.from} = ${fmt(q.rate,4)} ${f.to}</span>${tag('参考价','blue')}</div>${kv('汇兑服务费（示例 0.1%）',`<span id="fx-fee">${f.from} ${fmt(q.fee)}</span>`)}${note('费用从卖出金额内扣除。确认页会展示锁定报价和有效时间。')}${error()}<div class="formfooter">${b('获取报价','fx-next','primary')}</div>`:`<h2 style="margin-bottom:24px">确认兑换报价</h2><div class="quote-strip"><span>1 ${f.from} = ${fmt(q.rate,4)} ${f.to}</span><span id="quote-timer" class="${C.expired?'orange':'green'}">${C.expired?'报价已过期':'报价有效 '+Math.max(0,Math.ceil((C.expires-Date.now())/1000))+' 秒'}</span></div>${kv('卖出金额',f.from+' '+fmt(q.amount))}${kv('汇兑服务费',f.from+' '+fmt(q.fee))}${kv('实际参与兑换',f.from+' '+fmt(q.amount-q.fee))}${kv('实际收到',f.to+' '+fmt(q.received),'total')}${C.expired?note('当前报价已失效。重新获取报价后，需再次确认新金额。','warn'):note('确认后将从跨境宝扣除卖出金额，买入币种直接记入同一钱包。')}${error()}<div class="formfooter">${b('上一步','fx-edit')}${C.expired?b('重新获取报价','fx-refresh','primary'):b('确认兑换','fx-confirm','primary')}</div>`}</section><aside class="panel side-info"><h3>我的币种余额</h3>${Object.keys(M.rates).map(c=>kv(c,fmt(wallet.balances[c]))).join('')}<div class="divider-line"></div><p>此处兑换只调整跨境宝内的币种，不会改变国际站与 ACP 的币种余额。</p><p>采购时如需使用其他账户的外币，将在付款确认页展示对应汇兑方案，由你确认。</p>${link('设置付款时自动汇兑','go-settings')}</aside></div>`;}
function toggle(key,on){return `<button class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${{fx:'付款时自动汇兑',card:'银行卡补款',coupon:'优先使用权益',auto:'自动采购付款'}[key]||key}" data-action="setting-toggle" data-key="${key}"></button>`;}
function settingRow(title,description,action){return `<div class="setting-row"><div class="content"><h3>${title}</h3><p>${description}</p></div>${action}</div>`;}
function settingsPage(){const d=C.draft||S.settings;let body='';if(C.tab==='order')body=`<div class="form-layout"><section class="panel form-panel"><div class="sectionhead"><h2>优先从哪里扣款？</h2>${tag('余额优先','blue')}</div><p class="tiny muted">按下方顺序使用余额，不足时自动使用下一资金来源。上移或下移可调整顺序。</p><div class="sorting">${d.order.map((id,i)=>`<div class="sorting-row" draggable="true" data-source="${id}"><span class="handle" aria-hidden="true">⠿</span><span class="plan-num">${i+1}</span><span class="source-icon ${id}">${id==='wallet'?icon('wallet'):id==='acp'?'AP':'a'}</span><div class="name">${S.accounts[id].name}<p>${S.accounts[id].authorized?'可调用 '+money(M.equivalent(S.accounts[id].balances)):'授权未生效，付款时跳过'}</p></div><div class="moves"><button class="iconbtn" aria-label="上移${S.accounts[id].name}" data-action="move-source" data-index="${i}" data-dir="-1" ${i===0?'disabled':''}>${icon('sortup')}</button><button class="iconbtn" aria-label="下移${S.accounts[id].name}" data-action="move-source" data-index="${i}" data-dir="1" ${i===d.order.length-1?'disabled':''}>${icon('sortdown')}</button></div></div>`).join('')}</div>${settingRow('付款时自动汇兑','每个账户内优先使用支付币种，再按 USD、EUR 顺序换汇。付款确认页展示汇率和明细。',toggle('fx',d.fx))}${settingRow('余额不足时，允许银行卡补款','仅在三方余额不足时启用。每次展示补款金额并确认，不计入可采购余额。',toggle('card',d.card))}${settingRow('优先使用适用权益','仅抵扣符合使用条件的费用；确认页展示优惠。当前没有可用的减免券。',toggle('coupon',d.coupon))}${error()}<div class="formfooter">${b('恢复当前设置','settings-cancel')}${b('保存支付设置','settings-save','primary')}</div></section><aside><section class="panel side-info"><h3>当前顺序预览</h3><div class="timeline">${d.order.map((id,i)=>`<div class="timeline-item">${i+1}. ${S.accounts[id].name}<p>${i===0?'优先扣款':'上一账户不足时继续使用'}</p></div>`).join('')}<div class="timeline-item">${d.card?'4. 企业银行卡补款':'余额不足时暂停'}<p>${d.card?'需再次确认差额和银行卡':'提示差额，可转入或调整方案'}</p></div></div></section><section class="panel side-info"><h3>保存后怎样生效？</h3><p>新规则适用于下一笔付款。已提交的交易仍沿用提交时的方案。</p><p>这是账户优先级；并非按每一笔历史收款的入账时间排序。资金来源仍可在账单里追溯。</p></section></aside></div>`;
else if(C.tab==='accounts')body=`<section class="panel form-panel"><div class="sectionhead"><h2>资金来源与收款规则</h2>${b('+ 连接新渠道','new-channel','small')}</div>${['wallet','acp','intl'].map(id=>{const a=S.accounts[id];return `<div class="setting-row"><span class="source-icon ${id}">${id==='wallet'?icon('wallet'):id==='acp'?'AP':'a'}</span><div class="content"><h3>${a.name} ${tag(id==='wallet'?'钱包账户':a.authorized?'已授权使用余额':'未授权',a.authorized?'green':'orange')}</h3><p>可用余额折合 ${money(M.equivalent(a.balances))} · ${id==='wallet'?'可收款、采购、提现及汇兑':'资金留在原账户，授权后可用于采购'}</p></div>${link('账户详情','account',`data-id="${id}"`)}</div>${id!=='wallet'?`<div class="account-route"><label class="tiny muted" for="route-${id}">${a.name}新到账资金如何处理</label><select id="route-${id}" data-route="${id}"><option value="keep" ${d.route[id]==='keep'?'selected':''}>保留原账户，授权钱包调用</option><option value="wallet" ${d.route[id]==='wallet'?'selected':''}>可用后自动转入跨境宝</option></select><p class="tiny muted" style="margin-top:8px">只对规则生效后的新到账且可用资金执行，不迁移历史余额。</p></div>`:''}`;}).join('')}${S.channels.map(x=>`<div class="setting-row"><span class="source-icon">${icon('globe')}</span><div class="content"><h3>${esc(x.name)} ${tag('已连接（演示）','green')}</h3><p>商户号 ${esc(x.merchant)} · 入账位置：${x.route==='wallet'?'跨境宝':'渠道账户'} · 暂无余额</p></div></div>`).join('')}${note('授权只赋予资金使用权限，不移动余额。解除授权会立即从可采购余额中移除对应资金；已提交交易不受影响。')}${error()}<div class="formfooter">${b('保存入账规则','settings-save','primary')}</div></section>`;
else if(C.tab==='auto')body=`<div class="form-layout"><section class="panel form-panel"><h2>自动采购付款</h2>${settingRow('允许为关联采购单自动付款','外销订单匹配商品与供应商后，按授权范围发起采购付款。',toggle('auto',d.auto))}${note('自动生成采购单不等于自动扣款。先授权付款范围，资金未结算或余额不足时，采购单进入待办。')}<div class="field"><label>适用范围</label><div class="bankcard"><span class="source-icon intl">a</span><div><b style="font-size:13px">国际站外销单 → 1688 关联采购单</b><p>仅限已确认商品映射与供应商的订单</p></div></div></div><div class="form-row">${field('单笔自动付款上限（含费，CNY）','perOrder',d.perOrder,'超出后转人工确认','inputmode="decimal" data-setting="perOrder"')}${field('每日自动付款上限（含费，CNY）','perDay',d.perDay,'每日 00:00 北京时间重置','inputmode="decimal" data-setting="perDay"')}</div>${kv('授权供应商','义乌市星合日用品商行')}${kv('扣款顺序',d.order.map(x=>S.accounts[x].name).join(' → '))}${kv('自动付款失败','停止本次支付，生成待办并提醒')}${kv('银行卡自动补款','不适用，必须手动确认')}${error()}<div class="formfooter">${b('保存自动付款授权','settings-save','primary')}</div></section><aside class="panel side-info"><h3>什么情况下自动暂停？</h3><p>① 余额不足或资金尚未结算<br>② 金额超过单笔或每日限额<br>③ 资金来源授权失效<br>④ 订单或供应商超出授权范围</p><p>暂停后展示具体原因与下一步入口。重复通知或重试复用原付款单，避免重复扣款。</p>${link('体验限额拦截 '+icon('chevron'),'auto-preview')}</aside></div>`;
else body=`<section class="panel form-panel"><h2>银行卡与付款安全</h2>${settingRow('企业银行卡','管理已验证的同名银行卡；提现与补款用途分别授权。',b('管理银行卡','banks','small'))}${settingRow('支付验证','新收款方、敏感设置和资金操作需要核验操作人权限。',tag('已启用','green'))}${settingRow('角色权限','本原型使用企业管理员身份。正式方案区分查看、发起和审批权限。',link('查看权限说明','permissions'))}${note('本原型不收集真实银行卡号、密码、短信验证码，也不会发起真实资金交易。')}</section>`;
return `${head('支付设置','让每一次收付，都按你的经营习惯进行。')}<div class="subtabs">${[['order','支付顺序'],['accounts','资金来源与入账'],['auto','自动采购付款'],['security','银行卡与安全']].map(([id,n])=>`<button class="${C.tab===id?'active':''}" data-settingtab="${id}">${n}</button>`).join('')}</div>${body}`;}
function filteredTx(){const f=C.fields;return S.tx.filter(t=>(!f.type||f.type==='all'||t.type===f.type)&&(!f.status||f.status==='all'||t.status===f.status)&&(!f.search||[t.title,t.id,t.detail].join(' ').includes(f.search)));}
function recordsPage(){const rows=filteredTx();return `${head('资金明细','从收款到采购，每笔资金都能追溯。',b(icon('download')+' 导出当前明细','export'))}<section class="panel"><div class="toolbar"><select name="type" aria-label="交易类型"><option value="all">全部交易类型</option>${['收款','转入','付款','提现','汇兑'].map(x=>`<option ${C.fields.type===x?'selected':''}>${x}</option>`).join('')}</select><select name="status" aria-label="交易状态"><option value="all">全部交易状态</option>${['已完成','处理中','待入账','已退回','付款失败'].map(x=>`<option ${C.fields.status===x?'selected':''}>${x}</option>`).join('')}</select><input name="search" aria-label="搜索流水" placeholder="搜索交易名称、订单号或流水号" value="${esc(C.fields.search||'')}">${b(icon('search')+' 查询','records-search','primary small')}${b('重置','records-reset','small')}</div><div class="sectionhead" style="margin:0"><span class="tiny muted">2026-11-08 · 共 ${rows.length} 笔记录</span><span class="tiny muted">账户间转入不重复计为外部收入</span></div></section><section class="panel flush">${txTable(rows)}</section>${note('点击详情可查看原始收款渠道、外销单、采购单、各账户扣款与处理状态。跨币种交易保留原币金额。')}`;}
function benefitsPage(){return `${head('权益中心','把每一笔费用看清楚，让优惠用在适合的交易上。',link('权益使用设置','go-settings'))}${note('以下费率与权益为交互设计示例，不代表正式商户报价或服务承诺。')}<div class="benefit-grid"><section class="coupon">${tag('已生效 · 示例','blue')}<h3 style="margin-top:18px">采购支付服务费</h3><div class="coupon-value">0.125<span style="font-size:15px">%</span></div><p>适用演示采购付款，付款确认页展示本次费用。</p>${b('查看计算方式','fee-info','small')}</section><section class="coupon">${tag('已生效 · 示例','blue')}<h3 style="margin-top:18px">账户内币种兑换</h3><div class="coupon-value">0.10<span style="font-size:15px">%</span></div><p>从卖出金额中扣除，获取报价后再确认。</p>${b('去汇兑','go-fx','small')}</section><section class="coupon">${tag('企业服务','green')}<h3 style="margin-top:18px">统一资金账单</h3><div class="coupon-value">免费</div><p>收付流水、跨账户资金调拨统一查询与导出。</p>${b('查看资金明细','go-records','small')}</section></div><section class="panel" style="margin-top:23px"><h2>费用减免券</h2><div class="empty" style="padding:34px">当前暂无可用减免券<div class="tiny" style="margin-top:8px">如有符合条件的权益，将在付款前自动匹配并展示。</div></div></section>`;}
function helpPage(){return `${head('帮助中心','关于跨境宝，你可能想了解这些。')}<section class="panel form-panel help-list">${[['总资产和可采购余额有什么不同？','总资产覆盖三个账户的可用和冻结余额，按参考汇率折成人民币。可采购余额只包含已授权、已结算且允许采购的资金；待结算、冻结与未授权金额不计入。每笔支付还要检查场景限制、费用和实时汇率。'],['国际站和 ACP 的钱必须先转入吗？','本方案支持保留原账户并授权调用。只有选择转入时才发生资金划转，原账户扣减，跨境宝增加，合计资产不重复增加。'],['卖出一个商品，就可以马上自动采购吗？','可先生成关联采购单；能否自动付款，取决于可用资金、付款授权、额度与订单条件。外销货款还未结算时，不提前把应收款当作可用余额。'],['为什么不能直接把所有余额提现？','总资产包括不可用资金与其他渠道账户。提现入口暂按跨境宝余额设计，其他账户需要按其能力转入。银行卡币种也需要和提现币种匹配。'],['采购金额超出余额时会发生什么？','先显示货款加费用的应付总额、可用金额及差额，阻止直接扣款。用户可转入补足、调整来源；启用银行卡补款后，还需要确认本次差额。'],['付款处理中可以重试吗？','请先查询原交易状态。处理中资金处于占用状态，不能再次花费；成功后扣除，失败后释放。不要因页面超时直接创建一笔新付款。'],['原型里的汇率、费率、到账时效是真实的吗？','所有金额、汇率、费用、账号与时效均为设计演示。实际产品应接入各渠道的报价和账户能力，以交易确认页的实时结果为准。']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`;}
function resultPage(){const t=C.record;if(!t)return home();const pending=['处理中','待入账'].includes(t.status),fail=['已退回','付款失败'].includes(t.status);const title=t.type==='提现'?(pending?'提现申请已提交':fail?'提现已退回':'提现已到账'):t.type==='付款'?(pending?'付款处理中':fail?'付款未完成':'付款成功'):t.type==='汇兑'?'兑换成功':t.status==='待入账'?'等待银行入账':t.type==='转入'?'转入成功':'收款到账';return `${head(t.type+'结果','随时可在资金明细中追踪这笔交易。')}<section class="panel form-panel"><div class="result"><div class="result-icon ${pending?'pending':fail?'fail':''}">${icon(pending?'clock':fail?'close':'check')}</div><h2>${title}</h2><p>${esc(t.note||'账户余额与资金明细已同步更新。')}</p><div class="big mono">${esc(t.display)}</div><div class="receipt">${kv('交易流水号',t.id)}${kv('业务类型',t.title)}${kv('交易状态',tag(t.status,pending?'orange':fail?'red':'green'))}${t.bank?kv('到账银行卡',esc(t.bank)):''}${t.fee!==undefined?kv('服务费',t.currency+' '+fmt(t.fee)):''}${t.type==='付款'?kv('关联订单',esc(t.order||'202611080126')):''}${kv('提交时间',t.time)}${t.type==='转入'&&t.source!=='bank'?kv('转入后总资产',money(M.total(S))):''}</div><div class="result-actions">${pending?b(t.type==='转入'?'刷新入账状态（演示）':'查询处理结果（演示）','resolve-tx','primary','data-outcome="success"'):b('返回钱包','go-home','primary')}${b('查看交易详情','tx','',`data-id="${t.id}"`)}${pending?b(t.type==='提现'?'模拟银行退回':'模拟处理失败','resolve-tx','',`data-outcome="fail"`):b('再办一笔','again')}</div>${t.type==='付款'&&t.status==='已完成'?'<div class="finish-note">采购单已更新为「已付款」，关联外销订单保留。可在交易详情追溯三方资金扣款。</div>':''}${pending?'<div class="finish-note">处理中仅查询原交易，不生成新的扣款申请。预留金额暂不可用于其他付款。</div>':''}</div></section>`;}
const FLOWS={
 transfer:{name:'转入与收款',title:'多渠道资金转入，统一看到到账结果',intro:'先选择资金来源，再填写金额，确认是否真正划转；银行汇款等待入账后才增加可采购余额。',steps:[['T01','选择来源','转入','国际站 / ACP / 银行 / 其他','点击任一渠道，进入该渠道适用的转入流程。'],['T02','填写信息','从国际站转入','USD 1,000.00','选择币种，填写金额，可用余额实时校验。'],['T03','确认转入','转入跨境宝','实际到账 USD 1,000.00','展示费用、到账方式和原账户扣减规则。'],['T04','转入结果','转入成功','+ USD 1,000.00','账户余额同步更新，可继续查看原始流水。']],branches:[['unauth','渠道未授权','解释可调用权限，完成授权后返回原流程。'],['bankpending','银行转账待入账','展示汇款信息；等待入账，不提前增加额度。'],['pendingfunds','资金尚未结算','解释不可用原因，回到账户查看结算进度。']]},
 pay:{name:'采购 / 其他付款',title:'从一张采购单，到可解释的多账户扣款',intro:'先算货款 + 费用，再按支付顺序生成分账方案。外币转换、银行卡差额与异常结果都在确认前说清楚。',steps:[['P01','选择待付订单','付款','外销关联采购单','从钱包快捷入口或一级菜单「付款」进入。'],['P02','确认资金方案','本次合计需支付','CNY 120,150.00','展开跨境宝、ACP、国际站各扣多少及换汇明细。'],['P03','验证并提交','核验付款权限','确认本次扣款方案','通过演示验证后提交，避免重复点击创建新付款。'],['P04','付款结果','付款成功','− CNY 120,150.00','回写采购订单；查看交易详情与各账户扣款。']],branches:[['shortage','余额不足','应付总额超过可用金额时拦截，展示差额及补款入口。'],['paypending','付款处理中','占用资金，查询原交易，不允许重复发起。'],['payfail','付款失败','明确未扣款或已释放占用，调整后再试。']]},
 withdraw:{name:'提现',title:'从钱包余额，到同名企业银行卡',intro:'先选币种与银行卡，校验金额和费用，再确认申请。处理中、成功、银行退回三种状态都有明确出口。',steps:[['W01','选择账户','提现至银行卡','招商银行 · 尾号 6288','在提现一级菜单选择币种及同名银行卡。'],['W02','填写金额','提现到账金额','CNY 5,000.00','费用单列，可用金额必须覆盖到账金额 + 费用。'],['W03','核对申请','确认提现','合计扣除 CNY 5,002.00','核验主体、银行卡和费用，提交后先占用资金。'],['W04','追踪到账','提现处理中','预计 1–2 个工作日','查询银行结果；成功扣款，退回释放余额。']],branches:[['withdrawshort','提现余额不足','按对应币种校验，不以折算后的总资产抵扣。'],['nobank','没有可用银行卡','添加并验证同名企业银行卡，返回保留金额。'],['bankreturn','银行退回','说明退回原因，资金释放后可更换银行卡重试。']]},
 fx:{name:'汇兑',title:'先看清兑换结果，再确认有效报价',intro:'账户内汇兑单独操作；采购时的自动汇兑在付款页确认，两种入口共享清晰的费用与报价信息。',steps:[['F01','选择币种','美元兑换人民币','USD → CNY','选择卖出与买入币种，可交换方向。'],['F02','输入金额','卖出金额','USD 1,000.00','展示参考汇率、费用、预计收到金额。'],['F03','确认报价','报价有效 30 秒','实际收到 CNY 7,092.90','锁定报价后确认，失效时需要重新获取。'],['F04','到账结果','兑换成功','+ CNY 7,092.90','卖出币种扣减，买入币种增加，形成双币种流水。']],branches:[['quoteexpired','汇率过期','保留金额，重新报价并再次确认，不静默改价。'],['fxshort','卖出余额不足','只校验卖出币种的可用余额，提示上限。'],['samecurrency','买卖币种相同','阻止兑换，提示选择不同币种。']]},
 settings:{name:'支付顺序与授权',title:'把默认扣款习惯变成可调整的规则',intro:'账户顺序、账户内币种顺序、银行卡补款及收款入账位置分开设置；保存后仅影响新交易。',steps:[['S01','进入支付设置','支付设置','支付顺序 / 入账 / 自动付款','一级菜单直接进入，不藏在个人中心。'],['S02','调整顺序','优先从哪里扣款','跨境宝 → ACP → 国际站','可拖动或用上下箭头调整，右侧同步预览。'],['S03','查看补款规则','余额不足时银行卡补款','每次确认差额','银行卡不计入余额合计，也不会默认无感扣款。'],['S04','保存并生效','支付设置已保存','下一笔付款生效','返回付款页，按新顺序重新生成扣款方案。']],branches:[['unauth','取消某个账户授权','可采购余额立即重算，已提交交易不改变。'],['cardsettings','启用银行卡补款','先有同名银行卡，补款在每笔交易单独确认。'],['fxsettings','关闭自动汇兑','本次只使用支付币种，其他币种余额仍显示但不参与扣款。']]},
 auto:{name:'自动外销内采',title:'外销订单触发采购，付款仍受授权与资金约束',intro:'钱包承接采购单的资金执行。商品映射与采购策略由订单系统提供，资金未结算时不假设平台垫资。',steps:[['A01','授权范围','自动采购付款','国际站 → 1688','限定商家、供应商、订单场景与单笔 / 每日额度。'],['A02','订单触发','关联采购单已生成','TA202611080328','商品映射成立后产生采购单，保留两侧订单关联。'],['A03','执行前校验','检查资金与限额','本次需 CNY 120,150.00','检查结算状态、用途、授权、余额与付款限额。'],['A04','完成或转待办','超限转为手动确认','暂停自动付款','符合条件才扣款；异常给出下一步，并避免重复付款。']],branches:[['auto-limit','超过单笔自动限额','采购单保留，需管理员确认本次付款。'],['pendingfunds','外销收款还未结算','展示待结算余额，可选择已有可用资金付款。'],['shortage','自动付款资金不足','本次暂停，不静默调用银行卡或授信。']]}
};
function miniFrame(flow,step,i){const [code,label,title,value,caption]=step;return `<div class="frame-wrap"><div class="frame-label"><span>${code} / ${label}</span><span>PC</span></div><div class="frame" role="button" tabindex="0" data-action="flow-jump" data-flow="${flow}" data-step="${i}" aria-label="体验${label}"><div class="mini-top"><i></i><i></i><i></i><span>阿里国际站 · 跨境宝</span></div><div class="mini-body"><h4>${title}</h4>${i===3?`<div class="mini-result"><b>✓</b><div class="mini-value" style="font-size:13px">${value}</div></div><div class="mini-field">账户余额与交易明细同步</div><div class="mini-button">查看结果 / 体验此步</div>`:`<div class="mini-label">${i===0?'操作入口':i===1?'输入与选择':'确认信息'}</div><div class="mini-card">${value}</div><div class="mini-field">${flow==='pay'?'跨境宝余额 · 优先扣款':flow==='withdraw'?'企业同名账户 · 已验证':flow==='fx'?'服务费与实际到账金额':'账户信息与资金状态'}</div><div class="mini-field">${flow==='pay'?'其他资金来源 · 顺序补足':'可用余额 · 实时校验'}</div><div class="mini-button">${i===0?'进入流程':i===1?'下一步':'确认并继续'} →</div>`}</div></div><div class="frame-caption">${caption}</div></div>`;}
function flowPage(){const flow=FLOWS[C.flow]||FLOWS.pay;return `<div class="flowpage">${head('用户动线','像翻阅设计稿一样看完整流程，也可以点击画面直接体验。',tag('6 条主线 · 关键异常分支','blue'))}<div class="flowtabs">${Object.entries(FLOWS).map(([id,f])=>`<button class="${C.flow===id?'active':''}" data-flowtab="${id}">${f.name}</button>`).join('')}</div><div class="flowintro"><h2>${flow.title}</h2><p>${flow.intro}</p></div><div class="frames">${flow.steps.map((s,i)=>miniFrame(C.flow,s,i)).join('')}</div><div class="sectionhead"><h2>在这些情况下，流程如何分支？</h2><span class="tiny muted">点击卡片进入对应状态</span></div><div class="branch-grid">${flow.branches.map(([id,title,text])=>`<button class="branch" data-scenario="${id}"><h4>${title} ${icon('arrow')}</h4><p>${text}</p></button>`).join('')}</div><div class="panel side-info"><h3>评审时可以这样走一遍</h3><p style="margin:0">先看正常路径里的信息是否足够决策，再点击异常分支，看提示能否帮助商家继续操作。右下角「情景演示」可随时切换状态；「重置」恢复初始账户金额与设置。此视图中的结果卡可直接预览，不会改动余额。</p></div></div>`;}
function specPage(){return `${head('设计说明','这一版先把“钱在哪、能花多少、怎么扣”说明白，再串起每一步操作。',tag('方案假设 · 待业务评审','orange'))}<div class="spec-grid"><article class="spec-card"><h3>01 / 钱包的定位</h3><p><b>跨境宝是统一资金入口与调度层。</b>既管理自己的余额，也调用已授权的国际站、ACP 余额。三个账户保留独立账本，统一操作和查看。</p><p>商家是同一个企业主体，在国际站是卖家，在 1688 是采购方。到账货款可用于采购，剩余资金留存或提现；<b>资金余额不直接等于利润</b>。</p><p>本原型暂以「跨境宝」命名，支付宝与抖音只借鉴信息层级，保留 PC 端的左侧导航、表格、表单和侧栏。</p></article><article class="spec-card"><h3>02 / 资产与额度的计算</h3><div class="formula">总资产 = 三方账面余额的本币折算合计<br>可采购余额 = 三方已授权、已结算且允许采购的可用余额折算合计<br>本次应付 = 货款 + 费用 − 适用优惠</div><p>每笔交易还要按币种、用途、订单限额与资金占用重新校验。<b>本次应付大于本次可用时必须拦截</b>，显示差额；银行卡作为单独确认的补款渠道。</p><p>内部划转不增加资产。冻结与待结算金额不进入可采购余额，不重复计算跨账户在途资金。</p></article><article class="spec-card"><h3>03 / 收款与自动采购</h3><p><b>两个动作独立授权：</b>订单系统按商品映射生成采购单，钱包按资金与付款规则执行。卖出商品不代表收款已结算，更不代表已授权自动扣款。</p><p>新到账资金可留在原账户，或在可用后自动转入跨境宝。规则只影响未来资金。触发采购时记录关联外销单、采购单和付款单。</p><p>本原型展示授权配置与超限转人工路径；真实自动执行需后端事件驱动、主体校验及采购系统接入。</p></article><article class="spec-card"><h3>04 / 扣款与失败处理</h3><p>先按账户顺序，再按账户内币种顺序：<b>人民币 → 美元 → 欧元</b>。跨币种前显示汇率、费用和分账明细。下一账户只补足尚未覆盖的部分。</p><p>提交前校验余额版本并占用；处理中可查询原交易，不新建重复付款。失败释放占用；部分渠道结果不确定时保留处理中，由状态查询和补偿收敛。</p><p>前端原型模拟余额变动与占用；跨系统的一致性、幂等与补偿由正式交易服务实现。</p></article></div><section class="panel flush" style="margin-top:23px"><div class="panel-title"><h2>一级菜单与关键出口</h2><span class="tiny muted">操作可达性优先</span></div><table class="spec-table"><thead><tr><th>入口</th><th>商家要完成什么</th><th>完成后的去向</th></tr></thead><tbody>${[['钱包总览','看总资产、可采购余额、来源构成、待办和权益','转入 / 付款 / 提现 / 汇兑 / 设置'],['转入','选择渠道 → 选币种与金额 → 确认 → 到账或等待','更新余额，查看原始资金来源'],['付款','1688 或其他供应商 → 算费用与分账 → 验证 → 结果','采购单状态 + 资金明细'],['提现','选择币种与同名卡 → 金额 → 确认 → 跟踪到账','到账成功，或退回并释放占用'],['汇兑','选择币种 → 参考报价 → 有效报价 → 确认兑换','更新币种余额与双币种流水'],['支付设置','账户顺序、补款、资金授权、入账与自动付款','对后续新交易生效'],['资金明细','筛选、追溯、查询处理中交易、导出','查看外销单 / 采购单 / 资金子流水']].map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></section><section class="panel side-info"><h3>需要与业务、资金及合规伙伴确认的边界</h3><p>① 三方账户的主体映射、币种与跨产品调用权限；② 每类资金是否允许采购、提现和跨境结算；③ 手续费、汇率、到账时效、限额及退费口径；④ 银行卡能否支持采购差额补款；⑤ 跨账户拆分付款的占用、失败补偿、退款原路规则；⑥ 人员权限、审批与自动扣款授权方式。</p><p>上述能力是设计假设，未将其表述为已上线能力。所有原型金额、账户、汇率和时效均为演示数据；未连接真实资金系统。</p></section>`;}
let returnFocus=null;
function modal(title,body,footer='',drawer=false){returnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-bg ${drawer?'drawer-bg':''}"><section class="modal ${drawer?'drawer':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="iconbtn" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;$('#overlay button')?.focus();}
function closeModal(){const old=returnFocus;$('#overlay').innerHTML='';modalState=null;if(old?.isConnected)old.focus();}
function accountDrawer(id){if(id==='all'){quotaDrawer();return;}const a=S.accounts[id];modalState={kind:'account',id};modal(a.name+'账户',`<div class="account-top"><span class="source-icon ${id}">${id==='wallet'?icon('wallet'):id==='acp'?'AP':'a'}</span>杭州远帆贸易有限公司 ${tag(a.authorized?'已授权':'待授权',a.authorized?'green':'orange')}</div>${kv('账户可用余额（折合 CNY）',money(M.equivalent(a.balances)),'total')}<div class="divider-line"></div><h3 style="font-size:13px">按币种查看</h3>${Object.keys(M.rates).map(c=>`<div class="setting-row"><div class="content"><h3>${c}</h3><p>冻结 / 待结算 ${fmt(a.frozen[c])}</p></div><b class="mono">${fmt(a.balances[c])}</b></div>`).join('')}${note(id==='wallet'?'跨境宝自己的余额可用于采购、提现和汇兑。':'资金仍在'+a.name+'账户。授权后可以从钱包直接调度，转入时才发生真实划转。')}${id!=='wallet'?`<div class="tiny muted" style="margin-bottom:16px">授权范围：读取余额、按确认方案采购付款、主动转入跨境宝。仅同一企业主体。</div>${b(a.authorized?'解除余额调用授权':'授权使用余额','toggle-auth',a.authorized?'':'primary',`data-id="${id}"`)}`:''}`,b('查看相关明细','account-records','',`data-id="${id}"`)+b('完成','close-modal','primary'),true);}
function quotaDrawer(){modal('总资产与可采购余额',`<div class="tiny muted">总资产 · 折合 CNY</div><div class="account-value mono">${money(M.total(S))}</div><div class="divider-line"></div><h3 style="font-size:14px">可采购余额构成</h3>${['wallet','acp','intl'].map(id=>kv(S.accounts[id].name+(S.accounts[id].authorized?'':' · 未授权'),money(S.accounts[id].authorized?M.equivalent(S.accounts[id].balances):0))).join('')}${kv('可采购余额合计',money(M.available(S)),'total')}${note('这里的“额度”是现有可用余额合计，不是信用额度。银行卡余额不计入。')}<h3 style="font-size:13px;margin-top:23px">为什么本次付款可用金额可能不同？</h3><p class="tiny muted" style="margin-top:12px;line-height:2">汇率波动、用途限制、交易限额、自动汇兑设置和处理中占用，都会影响本次实际可用金额。付款前按货款 + 费用重新校验。</p><div class="divider-line"></div>${kv('演示折算汇率','USD 1 = CNY 7.1000<br>EUR 1 = CNY 8.0000')}${kv('总资产中的冻结 / 待结算',money(M.round(Object.values(S.accounts).reduce((n,a)=>n+M.equivalent(a.frozen),0))))}` ,b('去采购付款','go-pay','primary'),true);}
function txDrawer(id){const t=S.tx.find(t=>t.id===id)||(C.record?.id===id?C.record:null);if(!t)return;modalState={kind:'transaction',id};const pending=['处理中','待入账'].includes(t.status);modal('交易详情',`<div class="sectionhead"><h3>${esc(t.title)}</h3>${tag(t.status,pending?'orange':['付款失败','已退回'].includes(t.status)?'red':'green')}</div><div class="account-value mono" style="font-size:27px;margin:23px 0">${esc(t.display)}</div>${kv('交易流水号',t.id)}${kv('时间',t.time)}${kv('资金账户',S.accounts[t.source]?.name||'银行转入')}${kv('业务说明',esc(t.detail||''))}${t.order?kv('采购订单',esc(t.order)):''}${t.bank?kv('银行卡',esc(t.bank)):''}${t.native?kv('原币金额',t.currency+' '+fmt(t.native)):''}${t.received?kv('买入金额',t.to+' '+fmt(t.received)):''}${t.fee!==undefined?kv('服务费',t.currency+' '+fmt(t.fee)):''}${t.q?`<div class="divider-line"></div><h3 style="font-size:13px">账户扣款明细</h3>${t.q.allocations.map(a=>`<div class="plan-row"><div class="plan-name">${S.accounts[a.id].name}<p>${a.parts.map(p=>p.currency+' '+fmt(p.native)+(p.change?'（兑换余款 CNY '+fmt(p.change)+' 留存）':'')).join(' + ')}</p></div><div class="mono">${money(a.value)}</div></div>`).join('')}${t.q.cardAmount?kv('银行卡补款',money(t.q.cardAmount)):''}`:''}<div style="margin-top:20px">${note(esc(t.note||'本笔交易可追溯至关联订单与资金账户。'),pending?'warn':'')}</div><div class="timeline"><div class="timeline-item">申请已提交<p>${t.time}</p></div><div class="timeline-item">${pending?'渠道正在处理':t.status==='已退回'?'银行退回，资金已释放':t.status==='付款失败'?'未完成，余额未扣除':'处理完成'}<p>${pending?'请查询此原始交易状态':'余额与资金明细已更新'}</p></div></div>`,pending?b('查看处理结果','show-tx-result','primary',`data-id="${t.id}"`):b('关闭','close-modal','primary'),true);}
function bankModal(){modal('我的企业银行卡',`${S.banks.map(x=>`<div class="bankcard"><span class="bankicon">${icon('bank')}</span><div><b>${esc(x.name)} · ${x.tail}</b><p>${x.currency} · 同名企业账户</p></div>${tag('已验证','green')}</div>`).join('')}${note('提现币种需与银行卡币种一致。只展示银行名称和尾号，不展示完整卡号。')}`,b('+ 添加银行卡','add-bank','primary'));}
function addBankModal(){modalState={kind:'add-bank'};modal('添加同名企业银行卡',`${field('账户主体','bank-holder','杭州远帆贸易有限公司','','readonly')}${field('银行名称','bank-name','招商银行')}${select('账户币种','bank-currency',Object.keys(M.rates).map(c=>[c,c]),C.page==='withdraw'?C.fields.currency:'CNY')}${field('银行卡尾号（演示）','bank-tail','','仅输入 4 位演示尾号，无需真实卡号。','inputmode="numeric" maxlength="4"')}${note('正式流程需要验证企业主体与银行卡归属。本原型仅模拟验证结果。')}<div class="error-text" id="modal-error"></div>`,b('取消','close-modal')+b('验证并添加（演示）','bank-add-confirm','primary'));}
function verify(kind){modalState={kind:'verify',transaction:kind};const label={pay:'付款',transfer:'转入',withdraw:'提现',fx:'兑换'}[kind];modal('确认'+label+'权限',`<div style="text-align:center;padding:10px 0 20px"><div class="result-icon" style="width:52px;height:52px;background:#ecf3ff;color:#5284cb">${icon('shield')}</div><h3>核验本次资金操作</h3><p class="tiny muted" style="margin-top:10px">企业管理员 · 杭州远帆贸易有限公司</p></div>${kv('操作类型',label)}${kv('验证方式','企业支付权限验证（模拟）')}${note('原型演示：点击下方按钮直接模拟验证通过，无需填写密码或验证码。')}<div class="error-text" id="modal-error"></div>`,b('取消','close-modal')+b('模拟验证通过，确认'+label,'verify-submit','primary',`data-kind="${kind}"`));}
function resultPreview(type,status='已完成'){const config={pay:{type:'付款',title:'1688 采购付款',display:'− CNY 120,150.00',amount:120150,fee:150,currency:'CNY',source:'wallet',order:'202611080126',q:M.quote(S,120000),note:'采购单更新为已付款，以下为结果页面预览，未实际改动演示余额。'},transfer:{type:'转入',title:'国际站余额转入',display:'+ USD 1,000.00',native:1000,currency:'USD',source:'intl',fee:0,note:'原账户减少，钱包增加。此结果为设计预览，演示余额不变。'},withdraw:{type:'提现',title:'提现至招商银行',display:'CNY 5,000.00',native:5000,currency:'CNY',source:'wallet',bank:'招商银行 · 6288',fee:2,note:'提现已提交，金额暂时占用。此处为设计预览，演示余额不变。'},fx:{type:'汇兑',title:'美元兑换人民币',display:'+ CNY 7,092.90',native:1000,received:7092.9,to:'CNY',currency:'USD',source:'wallet',fee:1,note:'卖出 USD 1,000.00，费用 USD 1.00。此结果为预览，余额不变。'}};nav(type==='transfer'?'transfer':type,{stage:3,record:{id:'DEMO-PREVIEW-'+type,time:'2026-11-08 14:30',status,preview:true,...config[type]}});}
function submitTransaction(kind){if(C.stage===3)return;if(kind==='pay'){if(C.fields.card&&!S.settings.card)throw Error('银行卡补款授权已关闭，请重新确认方案');if(S.tx.some(t=>t.type==='付款'&&t.order===C.fields.order&&['已完成','处理中'].includes(t.status)))throw Error('该订单已存在付款，请查看原交易结果，勿重复提交');const amount=num('amount'),q=M.quote(S,amount,!!C.fields.card);if(!Number.isFinite(amount)||amount<=0||!q.ok)throw Error('资金或金额已变化，请重新确认');if(C.expired)throw Error('汇率已过期，请刷新报价');if(!C.fields.agreed)throw Error('请先确认扣款方案');const fail=C.scenario==='payfail',pending=C.scenario==='paypending';if(!fail){M.reserve(S,q);if(!pending)M.settle(S,q,true);}const r=addTx({type:'付款',title:C.fields.kind==='other'?'供应商付款':'1688 采购付款',detail:C.fields.supplier+(C.fields.external?' · 关联外销单 '+C.fields.external:' · 采购订单 '+C.fields.order),display:'− CNY '+fmt(q.due),currency:'CNY',amount:q.due,fee:q.fee,source:'wallet',order:C.fields.order,status:fail?'付款失败':pending?'处理中':'已完成',q,settled:!pending,note:fail?'渠道校验未通过，未扣除资金。请检查资金来源后重试。':pending?'资金已暂时占用，采购单等待付款结果。请查询原交易，勿重复付款。':'采购单已更新为已付款，三方账户余额已同步。'});C.record=r;
}else if(kind==='transfer'){const amount=num('amount'),f=C.fields;M.transfer(S,f.source,f.currency,amount);addTx({type:'转入',title:S.accounts[f.source].name+'余额转入',detail:S.accounts[f.source].name+' → 跨境宝 · 内部调拨',display:'+ '+f.currency+' '+fmt(amount),native:amount,currency:f.currency,amount:M.round(amount*M.rates[f.currency]),fee:0,source:f.source,status:'已完成',note:'转出账户已扣减，跨境宝同币种余额已增加，三方合计资产保持不变。'});
}else if(kind==='withdraw'){const f=C.fields,amount=num('amount'),fee=f.currency==='CNY'?2:f.currency==='USD'?5:4,total=M.round(amount+fee),bank=S.banks.find(x=>x.id===f.bank&&x.currency===f.currency);if(!bank||!Number.isFinite(amount)||amount<=0||total>S.accounts.wallet.balances[f.currency])throw Error('提现金额或银行卡不可用');S.accounts.wallet.balances[f.currency]=M.round(S.accounts.wallet.balances[f.currency]-total);S.accounts.wallet.frozen[f.currency]=M.round(S.accounts.wallet.frozen[f.currency]+total);addTx({type:'提现',title:'提现至'+bank.name,detail:'跨境宝 → '+bank.name+' · '+bank.tail,display:f.currency+' '+fmt(amount),native:amount,amount:total,fee,currency:f.currency,source:'wallet',bank:bank.name+' · '+bank.tail,status:'处理中',settled:false,note:'提现金额和费用已占用，等待银行处理。演示预计 1–2 个工作日到账。'});
}else if(kind==='fx'){if(C.expired||Date.now()>C.expires)throw Error('报价已过期，请重新获取');const f=C.fields,amount=num('amount'),q=M.exchange(S,f.from,f.to,amount);addTx({type:'汇兑',title:f.from+' 兑换 '+f.to,detail:'跨境宝账户内 · '+f.from+' → '+f.to,display:'+ '+f.to+' '+fmt(q.received),native:amount,received:q.received,to:f.to,fee:q.fee,currency:f.from,source:'wallet',amount:amount*M.rates[f.from],status:'已完成',note:'卖出 '+f.from+' '+fmt(amount)+'，汇兑费用 '+f.from+' '+fmt(q.fee)+'，买入币种已记入跨境宝。'});}returnToPay=kind==='pay'?null:returnToPay;persist();closeModal();C.stage=3;render();window.scrollTo(0,0);}
function resolveRecord(success){const t=C.record;if(t.preview){toast('这是结果预览；返回起点完成交易后可查询真实演示状态。');return;}if(t.settled||!['处理中','待入账'].includes(t.status)){toast('这笔交易已处理完成，无需重复提交');return;}if(t.type==='付款'){M.settle(S,t.q,success);t.status=success?'已完成':'付款失败';t.note=success?'采购付款已完成，资金占用转为扣款，采购单已更新。':'渠道处理失败，原账户资金占用已全部释放，请调整后重新付款。';}else if(t.type==='提现'){const w=S.accounts.wallet;w.frozen[t.currency]=M.round(w.frozen[t.currency]-t.amount);if(!success)w.balances[t.currency]=M.round(w.balances[t.currency]+t.amount);t.status=success?'已完成':'已退回';t.note=success?'银行处理成功，资金已到达指定同名账户。':'银行返回：账户状态异常。提现金额及费用已释放，可更换银行卡后重新发起。';}else if(t.type==='转入'){if(success)S.accounts.wallet.balances[t.currency]=M.round(S.accounts.wallet.balances[t.currency]+t.native);t.status=success?'已完成':'已退回';t.note=success?'银行来款已完成匹配，跨境宝余额和可采购余额已更新。':'来款信息未匹配，未记入钱包余额，请核对汇款主体与附言。';}t.settled=true;persist();render();}
function scenarioPopover(){return `<div class="scenario-pop"><h3>选择一个情景</h3><p>切换页面与演示状态。重置可恢复初始数据。</p>${[['shortage','采购余额不足'],['unauth','国际站未授权'],['paypending','付款处理中'],['payfail','付款失败'],['quoteexpired','汇兑报价过期'],['bankreturn','提现被银行退回'],['auto-limit','自动采购超过限额']].map(([id,n])=>`<button data-scenario="${id}">${n} <span style="margin-left:auto;color:#9aabc2">→</span></button>`).join('')}</div>`;}
function runScenario(id){closeModal();popup=false;if(id==='shortage'){orderOpen('shortage');return;}if(id==='unauth'){S.accounts.intl.authorized=false;persist();nav('transfer',{stage:1,fields:{source:'intl',currency:'USD',amount:'1000'}});return;}if(id==='pendingfunds'){nav('home');pendingFunds();return;}if(id==='bankpending'){nav('transfer',{stage:1,fields:{source:'bank',currency:'USD',amount:'1000'}});return;}if(id==='paypending'||id==='payfail'){orderOpen();C.scenario=id;render();toast(id==='paypending'?'完成付款后将进入处理中，可查询或模拟失败。':'完成付款后将展示渠道失败，余额不扣除。');return;}if(id==='quoteexpired'){nav('fx',{stage:1,expired:true,expires:0,fields:{from:'USD',to:'CNY',amount:'1000'}});return;}if(id==='withdrawshort'){nav('withdraw',{fields:{currency:'CNY',bank:'b1',amount:'500000'},error:'预计扣除金额超出该币种的跨境宝可用余额，请减少金额或先转入。'});return;}if(id==='nobank'){nav('withdraw',{fields:{currency:'EUR',bank:'',amount:'100'}});return;}if(id==='bankreturn'){nav('withdraw');toast('先提交提现，再点击“模拟银行退回”查看资金释放。');return;}if(id==='fxshort'){nav('fx',{fields:{from:'USD',to:'CNY',amount:'500000'},error:'卖出金额超过 USD 可用余额。'});return;}if(id==='samecurrency'){nav('fx',{fields:{from:'USD',to:'USD',amount:'1000'},error:'卖出与买入币种相同，请选择不同币种。'});return;}if(id==='cardsettings'){nav('settings');C.draft.card=true;render();return;}if(id==='fxsettings'){nav('settings');C.draft.fx=false;render();return;}if(id==='auto-limit'){nav('settings',{tab:'auto'});autoPreview();}}
function pendingFunds(){modal('国际站待结算资金',`${kv('关联外销订单','TA202611070016')}${kv('待结算金额','USD 3,000.00','total')}${note('客户已付款，资金尚未达到可支配状态，暂不计入可采购余额。','warn')}<div class="timeline"><div class="timeline-item">客户付款成功<p>已记录订单收款</p></div><div class="timeline-item">等待满足结算条件<p>当前状态，尚不可采购或转出</p></div><div class="timeline-item">结算后成为可用余额<p>按已设置的入账位置处理</p></div></div><p class="tiny muted">此处仅展示状态，具体结算条件与时间由渠道返回。</p>`,b('使用其他可用资金采购','go-pay','primary'),true);}
function autoPreview(){const due=120150,limit=S.settings.perOrder;modal('自动采购付款待办',`${tag('自动付款已暂停','orange')}${kv('采购单','202611080126')}${kv('关联外销单','TA202611080328')}${kv('本次含费金额',money(due))}${kv('单笔自动付款上限',money(limit))}${note(!S.settings.auto?'尚未开启自动付款授权。采购单已保留，可手动确认本次付款。':due>limit?'本次金额超过自动付款上限 '+money(due-limit)+'，需要管理员手动确认。':'本次金额在单笔上限内；正式执行仍需校验每日限额与订单状态。','warn')}<p class="tiny muted">原型演示此分支不实际自动扣款。手动确认仍使用统一付款方案。</p>`,b('查看自动付款设置','go-auto')+b('手动确认这笔采购','order','primary','data-order="normal"'));}
function flowJump(id,index){if(id==='transfer'){if(index===0)nav('transfer');else if(index===3)resultPreview('transfer');else nav('transfer',{stage:index,fields:{source:'intl',currency:'USD',amount:'1000'}});}else if(id==='pay'){if(index===0)nav('pay');else if(index===3)resultPreview('pay');else{orderOpen();if(index===2&&C.stage!==3){C.fields.agreed=true;render();verify('pay');}}}else if(id==='withdraw'){if(index===3)resultPreview('withdraw','处理中');else nav('withdraw',{stage:index===2?1:0});}else if(id==='fx'){if(index===3)resultPreview('fx');else nav('fx',{stage:index===2?1:0,expires:Date.now()+30000,expired:false});}else if(id==='settings'){nav('settings');if(index===2){C.draft.card=true;render();}if(index===3)toast('调整规则后点击保存，即可对后续新交易生效。');}else if(id==='auto'){if(index===0)nav('settings',{tab:'auto'});else if(index===1)nav('pay');else if(index===2)orderOpen();else{nav('settings',{tab:'auto'});autoPreview();}}}
function fail(message){C.error=message;render();return false;}
function saveSettings(){const d=C.draft;if(d.auto&&(!(Number(d.perOrder)>0)||!(Number(d.perDay)>0)||Number(d.perOrder)>Number(d.perDay)))return fail('自动付款限额必须大于 0，单笔上限不能超过每日上限。');if(d.card&&!S.banks.some(x=>x.currency==='CNY'))return fail('请先添加一张人民币同名企业银行卡。');for(const id of ['intl','acp'])if(d.route[id]==='wallet'&&!S.accounts[id].authorized)return fail(S.accounts[id].name+'尚未授权，不能设置自动转入。');if(d.auto&&!S.settings.auto){modal('确认自动采购付款授权',`${note('保存后，授权范围内的采购单可使用已有可用余额自动付款。')} ${kv('适用订单','国际站关联的 1688 采购单')}${kv('供应商','义乌市星合日用品商行')}${kv('单笔含费上限',money(d.perOrder))}${kv('每日含费上限',money(d.perDay))}${kv('银行卡自动补款','不适用')}<p class="tiny muted">本原型只保存演示设置，不会执行真实自动采购。</p>`,b('取消','close-modal')+b('确认授权并保存','settings-commit','primary'));return;}commitSettings();}
function commitSettings(){S.settings=JSON.parse(JSON.stringify(C.draft));persist();closeModal();C.error='';render();toast('设置已保存，将用于下一笔交易');}
function refreshAmountInput(target){const start=target.selectionStart,end=target.selectionEnd,name=target.name;render();const node=document.getElementById(name);node?.focus();try{node?.setSelectionRange(start,end);}catch{}}
document.addEventListener('input',e=>{const t=e.target;if(t.closest('#overlay'))return;if(t.dataset.setting){C.draft[t.dataset.setting]=t.value;return;}if(!t.name)return;C.fields[t.name]=t.type==='checkbox'?t.checked:t.value;C.error='';if(C.page==='pay'&&C.stage===1&&t.name==='amount'){C.fields.agreed=false;refreshAmountInput(t);}if(C.page==='withdraw'&&C.stage===0&&t.name==='amount')refreshAmountInput(t);if(C.page==='fx'&&C.stage===0&&t.name==='amount'){const q=fxCalc();$('#fx-received').innerHTML=fmt(q.received)+` <small style="font-size:14px;color:#7790b0">${C.fields.to}</small>`;$('#fx-fee').textContent=C.fields.from+' '+fmt(q.fee);}});
document.addEventListener('change',e=>{const t=e.target;if(t.closest('#overlay'))return;if(t.dataset.route){C.draft.route[t.dataset.route]=t.value;return;}if(t.name&&!t.dataset.setting){C.fields[t.name]=t.type==='checkbox'?t.checked:t.value;C.error='';if(t.name==='agreed')return;if(C.page==='withdraw'&&t.name==='currency')C.fields.bank=S.banks.find(b=>b.currency===t.value)?.id||'';if(t.tagName==='SELECT')render();}});
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-action],[data-scenario]');if(!el||el.disabled)return;if(el.dataset.nav){closeModal();nav(el.dataset.nav);return;}if(el.dataset.mode){C.mode=el.dataset.mode;popup=false;render();window.scrollTo(0,0);return;}if(el.dataset.flowtab){C.flow=el.dataset.flowtab;render();return;}if(el.dataset.paytab){C.tab=el.dataset.paytab;C.fields=C.tab==='other'?{supplier:'深圳市远航包装有限公司',recipient:'DEMO **** 9316',order:'PO202611080021',amount:'18000',purpose:'包装材料采购'}:{};render();return;}if(el.dataset.settingtab){C.tab=el.dataset.settingtab;C.error='';render();return;}if(el.dataset.scenario){runScenario(el.dataset.scenario);return;}const a=el.dataset.action;if(!a)return;
if(a==='close-modal'){closeModal();return;}if(a==='return-pay'){const fields={...returnToPay,agreed:false};returnToPay=null;closeModal();nav('pay',{stage:1,fields});return;}if(a.startsWith('go-')){const dest=a.slice(3);if(C.page==='pay'&&C.stage===1&&['settings','card','accounts'].includes(dest))returnToPay={...C.fields};closeModal();if(dest==='accounts'){nav('settings',{tab:'accounts'});return;}if(dest==='auto'){nav('settings',{tab:'auto'});return;}if(dest==='card'){nav('settings');C.draft.card=true;render();return;}nav(dest);return;}
if(a==='privacy'){C.privacy=!C.privacy;render();return;}if(a==='quota'){quotaDrawer();return;}if(a==='account'){accountDrawer(el.dataset.id);return;}if(a==='pending-funds'){pendingFunds();return;}if(a==='scenario'){popup=!popup;render();return;}if(a==='flow-jump'){flowJump(el.dataset.flow,Number(el.dataset.step));return;}if(a==='auto-preview'){autoPreview();return;}if(a==='profile'){modal('当前商家账户',`${kv('企业名称','杭州远帆贸易有限公司（演示）')}${kv('当前角色','企业管理员')}${kv('关联渠道','国际站、ACP、跨境宝')}${note('所有商家、账户和交易信息都是为产品评审构造的演示数据。')}`,b('完成','close-modal','primary'));return;}if(a==='notifications'){modal('消息提醒',`<div class="task-item"><div><h4>外销关联采购单待付款</h4><p>本次货款 CNY 120,000.00</p></div>${link('去处理','order','data-order="normal"')}</div><div class="task-item"><div><h4>国际站 USD 3,000.00 待结算</h4><p>结算后才可转入或采购</p></div>${link('查看','pending-funds')}</div>`,b('关闭','close-modal'));return;}
if(a==='reset'){modal('重置演示数据',`<p style="font-size:13px;color:#788aa3">恢复初始余额、支付设置、银行卡与演示账单，清除本次原型中进行的模拟操作。</p>`,b('取消','close-modal')+b('重置演示','reset-confirm','primary'));return;}if(a==='reset-confirm'){returnToPay=null;S=M.seed();persist();closeModal();nav('home');toast('已恢复初始演示数据');return;}
if(a==='transfer-select'){C.fields={source:el.dataset.id,currency:'USD',amount:'1000'};C.stage=1;C.error='';render();return;}if(a==='transfer-back'){nav('transfer');return;}if(a==='transfer-next'){const amt=num('amount'),f=C.fields;if(!Number.isFinite(amt)||amt<=0)return fail('请输入大于 0 的转入金额，最多两位小数。');if(!S.accounts[f.source].authorized)return fail('请先授权使用该资金来源。');if(amt>S.accounts[f.source].balances[f.currency])return fail('转入金额超过该币种可用余额，冻结和待结算资金不能转入。');C.stage=2;C.error='';render();return;}if(a==='transfer-edit'){C.stage=1;C.error='';render();return;}if(a==='transfer-confirm'){verify('transfer');return;}if(a==='auth-source'){accountDrawer(C.fields.source);return;}
if(a==='toggle-auth'){const id=el.dataset.id,authorized=S.accounts[id].authorized;if(authorized){modal('解除'+S.accounts[id].name+'余额调用授权',`${note('解除后，这个账户将不再参与新采购付款与转入，现有已提交交易继续处理。','warn')}${kv('本次将移除的可采购余额',money(M.equivalent(S.accounts[id].balances)))}`,b('取消','close-modal')+b('确认解除','auth-confirm','',`data-id="${id}" data-enabled="false"`));}else{modal('授权使用'+S.accounts[id].name+'余额',`${kv('账户主体','杭州远帆贸易有限公司')}${kv('授权范围','读取余额、按确认方案采购付款、转入跨境宝')}${note('授权后资金仍留在原账户，不会自动划转。可随时在资金来源设置中解除。')}`,b('取消','close-modal')+b('同意并授权（演示）','auth-confirm','primary',`data-id="${id}" data-enabled="true"`));}return;}if(a==='auth-confirm'){S.accounts[el.dataset.id].authorized=el.dataset.enabled==='true';persist();closeModal();render();toast('授权状态已更新，可采购余额已重新计算');return;}
if(a==='bank-intent'){const amt=num('amount'),f=C.fields;if(!Number.isFinite(amt)||amt<=0)return fail('请输入有效的计划转入金额。');addTx({type:'转入',title:'银行汇款转入',detail:'演示银行 → 跨境宝 · 待核对入账',display:f.currency+' '+fmt(amt),native:amt,currency:f.currency,amount:amt*M.rates[f.currency],fee:0,source:'bank',status:'待入账',settled:false,note:'已记录转入意向，当前余额未增加。银行来款完成匹配后才可使用。'});C.stage=3;render();return;}if(a==='copy-bank'){const str='【原型演示，不可实际汇款】杭州远帆贸易有限公司 · 演示银行 · DEMO **** 8632 · 附言 DEMO-YF-20261108';if(navigator.clipboard)navigator.clipboard.writeText(str).then(()=>toast('已复制演示收款信息')).catch(()=>modal('收款信息',`<p class="tiny">${str}</p>`,b('关闭','close-modal')));else modal('收款信息',`<p class="tiny">${str}</p>`,b('关闭','close-modal'));return;}if(a==='new-channel'){closeModal();nav('transfer',{stage:1,fields:{source:'channel',channelName:'海外独立站',merchant:'DEMO-YF001',channelRoute:'wallet'}});return;}if(a==='channel-connect'){const name=(C.fields.channelName??'海外独立站').trim(),merchant=(C.fields.merchant??'DEMO-YF001').trim();if(!name||!merchant)return fail('请填写渠道名称与演示商户号。');if(S.channels.some(x=>x.name===name))return fail('已连接同名渠道，请在资金来源中查看或使用不同名称。');S.channels.push({name,merchant,route:C.fields.channelRoute||'wallet'});persist();nav('settings',{tab:'accounts'});toast('新渠道已连接（演示），未增加资产或可采购余额');return;}
if(a==='max'){const f=C.fields;if(C.page==='transfer')f.amount=String(S.accounts[f.source]?.balances[f.currency]||0);if(C.page==='withdraw'){const fee=f.currency==='CNY'?2:f.currency==='USD'?5:4;f.amount=String(Math.max(0,M.round(S.accounts.wallet.balances[f.currency]-fee)));}if(C.page==='fx')f.amount=String(S.accounts.wallet.balances[f.from]);C.error='';render();return;}
if(a==='order'){closeModal();orderOpen(el.dataset.order||'normal');return;}if(a==='pay-back'){nav('pay');return;}if(a==='other-next'){const f=C.fields;if(!f.supplier?.trim()||!f.recipient?.trim()||!f.order?.trim()||!f.purpose?.trim())return fail('请填写完整的供应商、收款账户、业务单号及用途。');if(!Number.isFinite(num('amount'))||num('amount')<=0)return fail('请输入有效付款金额。');C.fields.kind='other';C.fields.agreed=false;C.stage=1;C.error='';render();return;}if(a==='pay-topup'){returnToPay={...C.fields};nav('transfer');toast('转入完成后，返回付款重新生成方案');return;}if(a==='card-fallback'){C.fields.card=true;C.fields.agreed=false;render();return;}if(a==='refresh-quote'){C.expired=false;C.fields.agreed=false;render();toast('已刷新扣款方案，请重新确认');return;}if(a==='pay-confirm'){if(!C.fields.agreed)return fail('请勾选确认收款方与本次扣款方案。');if(!C.quote?.ok)return fail('余额不足，请先补足差额。');verify('pay');return;}
if(a==='banks'){bankModal();return;}if(a==='add-bank'){addBankModal();return;}if(a==='bank-add-confirm'){const name=$('#bank-name').value.trim(),currency=$('#bank-currency').value,tail=$('#bank-tail').value.trim();if(!name||!/^\d{4}$/.test(tail)){$('#modal-error').textContent='请填写银行名称和 4 位数字尾号。';return;}if(S.banks.some(x=>x.name===name&&x.tail===tail&&x.currency===currency)){$('#modal-error').textContent='该银行卡已存在，请勿重复添加。';return;}const id='b'+Date.now();S.banks.push({id,name,currency,tail,status:'可用'});persist();if(C.page==='withdraw'){C.fields.currency=currency;C.fields.bank=id;}closeModal();render();toast('银行卡已验证并添加（演示）');return;}if(a==='select-bank'){C.fields.bank=el.dataset.id;render();return;}if(a==='withdraw-next'){const f=C.fields,amt=num('amount'),fee=f.currency==='CNY'?2:f.currency==='USD'?5:4;if(!Number.isFinite(amt)||amt<=0)return fail('请输入大于 0 的提现金额，最多两位小数。');if(!S.banks.some(b=>b.id===f.bank&&b.currency===f.currency))return fail('请先选择支持此币种的银行卡。');if(M.round(amt+fee)>S.accounts.wallet.balances[f.currency])return fail('提现金额加服务费超过该币种可用余额。最多可到账 '+f.currency+' '+fmt(Math.max(0,S.accounts.wallet.balances[f.currency]-fee))+'。');C.stage=1;C.error='';render();return;}if(a==='withdraw-edit'){C.stage=0;render();return;}if(a==='withdraw-confirm'){verify('withdraw');return;}
if(a==='swap-fx'){const f=C.fields;[f.from,f.to]=[f.to,f.from];C.error='';render();return;}if(a==='fx-next'||a==='fx-refresh'){const f=C.fields,amt=num('amount');if(f.from===f.to)return fail('请选择不同的卖出和买入币种。');if(!Number.isFinite(amt)||amt<=0)return fail('请输入大于 0 的卖出金额，最多两位小数。');if(amt>S.accounts.wallet.balances[f.from])return fail('卖出金额超出 '+f.from+' 可用余额。');C.stage=1;C.expires=Date.now()+30000;C.expired=false;C.error='';render();return;}if(a==='fx-edit'){C.stage=0;C.error='';render();return;}if(a==='fx-confirm'){if(C.expired||Date.now()>C.expires){C.expired=true;render();return;}verify('fx');return;}
if(a==='verify-submit'){try{submitTransaction(el.dataset.kind);}catch(err){const msg=err.message||'交易未完成，请检查后重试。';closeModal();C.error=msg;if(el.dataset.kind==='fx')C.expired=true;render();}return;}if(a==='resolve-tx'){resolveRecord(el.dataset.outcome!=='fail');return;}if(a==='again'){nav(C.page);return;}if(a==='tx'){txDrawer(el.dataset.id);return;}if(a==='show-tx-result'){const t=S.tx.find(x=>x.id===el.dataset.id)||C.record;closeModal();nav(({付款:'pay',转入:'transfer',提现:'withdraw',汇兑:'fx'})[t.type]||'home',{stage:3,record:t});return;}
if(a==='setting-toggle'){const key=el.dataset.key;C.draft[key]=!C.draft[key];render();return;}if(a==='move-source'){const i=Number(el.dataset.index),j=i+Number(el.dataset.dir),order=C.draft.order;if(j>=0&&j<order.length)[order[i],order[j]]=[order[j],order[i]];render();return;}if(a==='settings-save'){saveSettings();return;}if(a==='settings-commit'){commitSettings();return;}if(a==='settings-cancel'){C.draft=JSON.parse(JSON.stringify(S.settings));C.error='';render();toast('已恢复当前保存的设置');return;}if(a==='permissions'){modal('操作权限说明',`${kv('查看者','查看余额、账户和交易明细')}${kv('经办人','发起转入、付款、提现、汇兑')}${kv('审批人','确认超限付款及指定资金操作')}${kv('企业管理员','管理资金来源、银行卡和自动付款授权')}${note('正式权限矩阵与审批阈值待业务确认；原型当前使用企业管理员身份。')}`,b('知道了','close-modal','primary'));return;}
if(['account-records','transfer-records','fx-records'].includes(a)){closeModal();nav('records',{fields:{type:a==='transfer-records'?'转入':a==='fx-records'?'汇兑':'all'}});return;}if(a==='records-search'){render();return;}if(a==='records-reset'){C.fields={};render();return;}if(a==='export'){const rows=[['交易流水','交易名称','时间','账户','原币金额','状态','备注'],...filteredTx().map(t=>[t.id,t.title,t.time,S.accounts[t.source]?.name||'银行',t.display,t.status,t.note||''])];const csv='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='跨境宝_演示资金明细.csv';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出演示资金明细');return;}if(a==='fee-info'){modal('采购服务费说明',`${kv('演示费率','0.125%')}${kv('示例货款','CNY 120,000.00')}${kv('服务费','CNY 150.00')}${kv('合计应付','CNY 120,150.00','total')}${note('费用用于产品流程演示。正式费率、优惠和多渠道费用以接入方规则为准。')}`,b('去付款','go-pay','primary'));return;}
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.frame'))e.target.click();if(e.key==='Escape'){closeModal();if(popup){popup=false;render();}}if(e.key==='Tab'&&$('#overlay').children.length){const nodes=[...$('#overlay').querySelectorAll('button:not(:disabled),input,select,[tabindex="0"]')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
let dragged=null;document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-source]');if(row)dragged=row.dataset.source;});document.addEventListener('dragover',e=>{if(e.target.closest('[data-source]'))e.preventDefault();});document.addEventListener('drop',e=>{const row=e.target.closest('[data-source]');if(!row||!dragged||!C.draft)return;e.preventDefault();const order=C.draft.order,from=order.indexOf(dragged),to=order.indexOf(row.dataset.source);order.splice(from,1);order.splice(to,0,dragged);dragged=null;render();});
setInterval(()=>{if(C.page==='fx'&&C.mode==='app'&&C.stage===1&&!C.expired){const remaining=Math.max(0,Math.ceil((C.expires-Date.now())/1000));if(remaining<=0){C.expired=true;render();}else if($('#quote-timer'))$('#quote-timer').textContent='报价有效 '+remaining+' 秒';}},1000);
const initial=location.hash.slice(1);fresh(navs.some(x=>x[0]===initial)?initial:'home');
